// The Q-full chip: host-side start/token/length, eight tokens generated by the chip itself, the
// last token compared with GraphL2. tests/test_tile_chip.py drives it.
`timescale 1ns/1ps
`default_nettype none

module tile_chip_tb ();
  parameter integer HIDDEN = 32;
  parameter integer RES = 16;
  parameter integer LAYERS = 2;
  parameter integer LENGTH = 8;

  reg clk = 1'b0;
  reg rst_n = 1'b0;
  always #5 clk = ~clk;

  reg start = 1'b0;
  reg [23:0] token = 24'd3;
  reg [15:0] length = LENGTH;
  wire busy;
  wire done;
  wire [23:0] next_token;
  wire [15:0] obs_word;
  reg [15:0] obs_addr = 16'd0;

  tile_chip dut (
    .clk(clk), .rst_n(rst_n), .start(start), .token(token), .length(length),
    .busy(busy), .done(done), .next_token(next_token), .obs_addr(obs_addr), .obs_word(obs_word)
  );

  reg [23:0] expected;
  reg [23:0] exp_mem [0:0];
  integer timeout, up, errors;

  initial begin
    errors = 0;
    $readmemh("exp_token.hex", exp_mem);
    expected = exp_mem[0];
    repeat (3) @(posedge clk);
    rst_n = 1'b1;
    @(posedge clk);
    start = 1'b1;
    @(posedge clk);
    start = 1'b0;
    up = 0;
    timeout = 0;
    while (!up && timeout < 20) begin
      @(posedge clk);
      up = busy;
      timeout = timeout + 1;
    end
    if (!up) begin
      $display("FAIL the chip never started");
      errors = errors + 1;
    end else begin
      timeout = 0;
      while (!done && timeout < 2000000) begin
        @(posedge clk);
        timeout = timeout + 1;
      end
      if (!done) begin
        $display("FAIL timeout after %0d cycles", timeout);
        errors = errors + 1;
      end
    end
    #1;
    if (next_token !== expected) begin
      $display("FAIL next_token %0d, expected %0d", next_token, expected);
      errors = errors + 1;
    end
    if (errors == 0) $display("PASS");
    else $display("FAIL %0d errors", errors);
    $finish;
  end

endmodule
